CREATE POLICY "team media master write" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='saha-media' AND (storage.foldername(name))[1]=public.current_team()::text AND public.is_team_usta());
CREATE POLICY "team media allowed read" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='saha-media' AND (storage.foldername(name))[1]=public.current_team()::text AND (public.is_team_usta() OR EXISTS(SELECT 1 FROM public.work_records w WHERE w.id::text=(storage.foldername(name))[2] AND w.owner_id=auth.uid() AND w.team_id=public.current_team() AND w.kind='job')));
CREATE POLICY "team media master delete" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='saha-media' AND (storage.foldername(name))[1]=public.current_team()::text AND public.is_team_usta());